def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def fibonacci(n):
    if n < 0:
        raise ValueError('n은 0 이상이어야 합니다')
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

function removeDuplicates(arr) {
  if (!Array.isArray(arr)) throw new TypeError('배열을 입력해야 합니다');
  return [...new Set(arr)];
}

function reverseString(str) {
  if (typeof str !== 'string') return '';
  return [...str].reverse().join('');
}

def add(a, b):
    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
        raise TypeError('numbers required')
    return a + b

